import { snd } from "../audio/sound.js";
import { RUINS } from "../world/terrain-state.js";
import { hudDisplayState } from "../ui/hud-state.js";
import { playersState } from "./players.js";
import { TS } from "./rules.js";
import { sessionState } from "./session.js";

/* Ancient ruins (generated by terrain.js, far from the castle): the first player unit that walks up to one loots it, once.
   Deterministic: no random numbers, the kind of loot depends on the ruin's own variant, the amount on its distance from the castle. */
const KINDS = [
  ["an old vault of coins and stone", { g: 1, s: 0.6 }],
  ["a ruined granary and woodpile", { w: 1, f: 0.8 }],
  ["a forgotten treasury", { g: 1.6 }],
];
const NAME = { g: "gold", w: "wood", s: "stone", f: "food" };

export function updateRuins(dt) {
  /* every .5 s of simulation time, decided from sessionState.time alone: a module-level timer is outside the save and reset, so it
     started at a different phase on each co-op machine (and after a resync) and the loot landed on different ticks */
  if (Math.floor(sessionState.time * 2) === Math.floor((sessionState.time - dt) * 2)) return;
  if (!RUINS.size) return;
  for (const r of RUINS.values()) {
    if (r.done) continue;
    for (const u of sessionState.units) {
      if (u.t !== 0 || u.hp <= 0) continue;
      const dx = u.x - r.x,
        dy = u.y - r.y;
      if (dx * dx + dy * dy > 2.5 * TS * (2.5 * TS)) continue;
      r.done = true;
      const K = KINDS[r.v % KINDS.length],
        base = 40 + r.d * 0.8,
        R = playersState.RESP[u.pl | 0] || playersState.RESP[0],
        got = [];
      for (const k in K[1]) {
        const n = Math.round(base * K[1][k]);
        R[k] = (R[k] || 0) + n;
        got.push("+" + n + " " + NAME[k]);
      }
      snd("ruin", r.x, r.y);
      hudDisplayState.msgS = "Ruins explored: " + K[0] + " (" + got.join(", ") + ")";
      hudDisplayState.msgT = 8;
      break;
    }
  }
}
